function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 99999) return 'edges needs 1 to 99999 pairs (2 to 10^5 nodes).';
  const n = edges.length + 1;
  const root = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => {
    while (root[x] !== x) {
      root[x] = root[root[x]];
      x = root[x];
    }
    return x;
  };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || u > n || v < 1 || v > n) return `Node labels are between 1 and ${n} (edges.length + 1).`;
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree: no cycles, self-loops or repeated edges.';
    root[a] = b;
  }
  return null;
}

