  const MOD = 1_000_000_007;
  const n = edges.length + 1;
  const depth = new Array(n + 1).fill(-1);
  depth[1] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (const [u, v] of edges) {
      if (depth[u] >= 0 && depth[v] < 0) { depth[v] = depth[u] + 1; changed = true; }
      else if (depth[v] >= 0 && depth[u] < 0) { depth[u] = depth[v] + 1; changed = true; }
    }
