function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 10);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // Position 0 is the root (label 1); every later position hangs below an earlier one.
  const labels = [1, ...shuffle(Array.from({ length: n - 1 }, (_, i) => i + 2))];
  const shape = Math.floor(rand() * 5);
  const edges = [];
  for (let i = 1; i < n; i++) {
    let parent;
    if (shape === 0) parent = Math.floor(rand() * i);
    else if (shape === 1) parent = rand() < 0.85 ? i - 1 : Math.floor(rand() * i);
    else if (shape === 2) parent = rand() < 0.8 ? 0 : Math.floor(rand() * i);
    else if (shape === 3) parent = Math.max(0, i - 1 - Math.floor(rand() * 3));
    else parent = i < 3 ? 0 : i - 2;
    edges.push(rand() < 0.5 ? [labels[parent], labels[i]] : [labels[i], labels[parent]]);
  }
  return [shuffle(edges)];
}
